const expectedToken = env.get("FACEREC_WEBHOOK_TOKEN");
const receivedToken = msg.req.get("x-facerec-token") || "";
const source = msg.req.ip || msg.req.socket?.remoteAddress || "unknown";
const allowedSources = new Set([
    "<HYPERVISOR_IP>",
    "::ffff:<HYPERVISOR_IP>",
    "127.0.0.1",
    "::1",
    "::ffff:127.0.0.1"
]);

function reject(statusCode, error) {
    msg.statusCode = statusCode;
    msg.headers = {
        "content-type": "application/json",
        "cache-control": "no-store"
    };
    msg.payload = { ok: false, error, source };
    return [null, null, msg];
}

if (!allowedSources.has(source)) {
    node.warn(`Rejected FaceRec event from ${source}`);
    return reject(403, "source_not_allowed");
}
if (!expectedToken) {
    node.error("FACEREC_WEBHOOK_TOKEN is not configured");
    return reject(503, "token_not_configured");
}
if (receivedToken !== expectedToken) {
    node.warn(`Rejected FaceRec token from ${source}`);
    return reject(401, "unauthorized");
}

const body = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
if (!new Set(["recognized", "unknown"]).has(body.event_type)) {
    return reject(422, "invalid_event_type");
}
if (body.event_type === "recognized" && !body.employee) {
    return reject(422, "recognized_event_requires_employee");
}

const now = Date.now();
const lastActionAt = context.get("lastActionAt") || 0;
const cooldownMs = 5000;
const retryAfterMs = cooldownMs - (now - lastActionAt);
if (retryAfterMs > 0) {
    msg.statusCode = 429;
    msg.headers = {
        "content-type": "application/json",
        "cache-control": "no-store",
        "retry-after": String(Math.ceil(retryAfterMs / 1000))
    };
    msg.payload = { ok: false, error: "cooldown_active", retry_after_ms: retryAfterMs };
    return [null, null, msg];
}

context.set("lastActionAt", now);
msg.facerec = {
    event_type: body.event_type,
    event_id: body.event_id ?? null,
    employee: body.employee || null,
    similarity: body.similarity ?? null,
    source
};
msg.sound_action = body.event_type === "recognized" ? "recognized_sound" : "unknown_sound";
msg.payload = "";
node.status({ fill: "blue", shape: "dot", text: msg.sound_action });
return body.event_type === "recognized" ? [msg, null, null] : [null, msg, null];

let code = null;
if (typeof msg.payload === "number") {
    code = msg.payload;
} else if (msg.payload && typeof msg.payload.code === "number") {
    code = msg.payload.code;
}
const ok = code === 0;
msg.statusCode = ok ? 200 : 500;
msg.headers = { "content-type": "application/json", "cache-control": "no-store" };
msg.payload = {
    ok,
    action: ok ? msg.sound_action : "sound_failed",
    event_type: msg.facerec?.event_type || null,
    event_id: msg.facerec?.event_id || null,
    employee: msg.facerec?.employee || null,
    source: msg.facerec?.source || null,
    exit_code: code
};
node.status({ fill: ok ? "green" : "red", shape: ok ? "dot" : "ring", text: ok ? msg.sound_action : `failed rc=${code}` });
return msg;
